import { useState } from 'react';
import type {
  ArtifactRef,
  InteractionSnapshot,
  NavigationTarget,
  ProcessClient,
} from '@wright/process-client';
import {
  ProcessUI,
  ProgressPanel,
  ReasonNotice,
  ResultCard,
  Section,
  WorkingControls,
} from '@wright/ui-kit';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

export default function App({ client, snapshot, readOnly }: AppProps) {
  const [navigationError, setNavigationError] = useState(false);
  const outputs = snapshot.outputs ?? [];
  const baseline = outputs.filter(output => output.role.startsWith('baseline_40'));
  const revision = outputs.filter(output => output.role.startsWith('revision_60'));
  const compared = new Set([...baseline, ...revision]);
  const shared = outputs.filter(output => !compared.has(output));

  const navigate = (target: NavigationTarget) => {
    setNavigationError(false);
    void client.navigate(target).catch(() => setNavigationError(true));
  };

  const openEvidence = (reference: ArtifactRef) => navigate({
    kind: 'evidence',
    artifact_ref: reference.artifact_ref,
    result_id: reference.result_id,
  });

  const renderResult = (output: (typeof outputs)[number]) => (
    <ResultCard
      key={output.result_id}
      output={output}
      onNavigate={navigate}
      onOpen={openEvidence}
    />
  );

  return <ProcessUI>
    <Section title="Heat-spreader candidate comparison">
      {readOnly && <p>Preview — controls remain read-only and no process changes will be made.</p>}
      <ProgressPanel state={snapshot.state} observations={snapshot.observations ?? []} />
      {(snapshot.diagnostics ?? []).map((reason, index) =>
        <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />)}
      {navigationError && <p role="alert">
        Wright could not open that destination. Use the common working view below to
        reconcile the current process or inspect the exact recorded result.
      </p>}
    </Section>

    <Section title="Prepare, run, and review">
      <WorkingControls
        client={client}
        snapshot={snapshot}
        readOnly={readOnly}
        onNavigate={navigate}
      />
    </Section>

    <Section title="Candidate results">
      {outputs.length === 0 && <p>Results will appear when supplied by the process.</p>}
      <table>
        <caption>Current results grouped by recorded candidate role</caption>
        <thead><tr><th scope="col">Baseline 40</th><th scope="col">Revision 60</th></tr></thead>
        <tbody><tr>
          <td>{baseline.map(renderResult)}</td>
          <td>{revision.map(renderResult)}</td>
        </tr></tbody>
      </table>
      {shared.length > 0 && <section aria-labelledby="shared-results">
        <h3 id="shared-results">Shared evidence and checks</h3>
        {shared.map(renderResult)}
      </section>}
    </Section>

    <Section title="Engineering limitations">
      <p>
        Result availability, artifact validity, previews, and compliance are separate.
        No artifact-specific viewer is declared here; use each exact result or evidence
        link for supported inspection. Missing or stale observations remain unavailable
        or stale until the authoritative snapshot reports otherwise.
      </p>
    </Section>
  </ProcessUI>;
}
